<?php require __DIR__.'/_admin.php';$p=db();$total=$p->query('SELECT COUNT(*) FROM quotations')->fetchColumn();$new=$p->query("SELECT COUNT(*) FROM quotations WHERE status = 'new'")->fetchColumn();$prods=$p->query('SELECT COUNT(*) FROM products WHERE active=1')->fetchColumn();$recent=$p->query('SELECT id,reference,customer_name,phone,product,status,created_at FROM quotations ORDER BY id DESC LIMIT 10')->fetchAll();admin_header('Dashboard');flash_show();?><div class="stat-grid"><div class="stat"><small>Total enquiries</small><strong><?=e((string)$total)?></strong></div><div class="stat"><small>New enquiries</small><strong><?=e((string)$new)?></strong></div><div class="stat"><small>Active products</small><strong><?=e((string)$prods)?></strong></div></div><div class="panel"><div class="panel-header"><h2>Latest quotation enquiries</h2><a href="quotes.php" class="admin-btn small">See All →</a></div><div class="table-scroll"><table><thead><tr><th>Reference</th><th>Customer</th><th>Phone</th><th>Product</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach($recent as $row):?><tr><td><a href="quotes.php?id=<?=e((string)$row['id'])?>"><?=e($row['reference'])?></a></td><td><?=e($row['customer_name'])?></td><td><?=e($row['phone'])?></td><td><?=e($row['product'])?></td><td><span class="status-chip"><?=e(ucfirst($row['status']))?></span></td><td><?=e($row['created_at'])?></td></tr><?php endforeach;?><?php if(!$recent):?><tr><td colspan="6">No enquiries yet. Quotation form submissions will appear here after the backend is configured.</td></tr><?php endif;?></tbody></table></div></div><?php admin_footer(); ?>
